def run(arguments: dict) -> dict:
    """Deduplicate an input list of strings while preserving original order."""
    items = arguments.get("items", [])
    case_sensitive = arguments.get("case_sensitive", True)

    seen = set()
    result = []

    for item in items:
        key = item if case_sensitive else item.lower()
        if key not in seen:
            seen.add(key)
            result.append(item)

    return {
        "result": result,
        "count": len(result),
        "duplicates_removed": len(items) - len(result),
    }

